// 教学伪代码
let p = reserve<Node>();
read(p.value);             // 不合法：只有位置，还没有 Node
initialize(p, { value: 1 });
read(p.value);             // 初始化与发布条件满足后才可读
let x = None;
read(x.value);             // 仍需先确认是有值的分支

// 教学伪代码
let bytes = buffer(8);
read(bytes, 7, 1);         // [7,8)：在范围内
read(bytes, 7, 4);         // [7,11)：越界
let k = keyFromOtherPool;
pool.resolve(k);          // 数字看似相同，也必须验证所属身份

// 教学伪代码
let list = makeVector();
let old = borrowSlice(list);
list.replaceBuffer();     // 即使 list 还活着，也会影响 old
read(old[0]);              // 必须被禁止或由真实存储保护
// 同理：return 指向局部对象的地址，不能靠改注解延长对象生命

// 教学伪代码
let a = own(block);
let b = move(a);           // 责任交给 b
drop(a);                  // 不得再按完整拥有值释放
drop(b);                  // 只履行这份实际责任
// 把一个 Arena 节点地址移出，并不自动得到独立 free 整块的权利

// 教学伪代码
let a = node, b = node;
let view = borrowRead(a.payload);
b.replacePayload();       // 会破坏 view 时必须排除
// 并发时，两次 value++ 也不能因对象由共享指针保活就免于同步
// 两个不同图根仍可能最终指向同一节点

// 教学伪代码
let op = device.submit(buffer);
op.requestCancel();
free(buffer);              // 请求已发出，不代表设备已停止
await op.reap();            // 确认完成并取回责任
// 只有其他依赖也结束后，才能释放
// 外部函数声明“不保留指针”，也需要实现真的履行

// 教学伪代码
type A = { bits: Int32 };
type B = { bits: Float32 };
// 大小可能相同，但运算、位模式或清理不同，不能直接共用错误实现
// 同样：私有正文变化后，旧的“不会写入”假设必须按真实依赖复核

// 教学伪代码
a.next = strong(b); b.next = strong(a);
// 没有悬空访问，不代表这个强拥有环会被自动回收
let retired = keepAtMost(4, nodeWithHugeBuffer);
// 责任数量 ≤ 4，不代表保留字节数已知
// 规范要求支持某场景，也不等于当前编译器已通过该场景验收

code.rust:
